/* field extraction */
.fx{display:grid;grid-template-columns:1.1fr 1fr;width:100%;max-width:960px;border:1px solid var(--line);background:var(--panel)}
.fx-doc{border-right:1px solid var(--line);display:flex;flex-direction:column}
.fx-dh{display:flex;align-items:center;gap:8px;padding:12px 16px;border-bottom:1px solid var(--line)}
.fx-p{margin:0;padding:18px 20px;font-size:14px;line-height:1.85;color:var(--text-dim)}
.fx-s{transition:background-color .35s,color .35s,box-shadow .35s;padding:1px 0}
.fx-s.hit{background:var(--accent-bg);color:var(--text);box-shadow:inset 0 -1px 0 var(--accent)}
.fx-s.hov{background:rgba(255,133,13,.22)}
.fx-fh{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--line)}
.fx-fh .t{font-weight:600;font-size:14px}
.fx-f{display:grid;grid-template-columns:110px 1fr;gap:10px;align-items:baseline;padding:11px 16px;border-bottom:1px solid var(--line);transition:background-color .25s}
.fx-f:last-child{border-bottom:0}
.fx-f:hover{background:rgba(var(--fg-rgb),.02)}
.fx-f .l{font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted)}
.fx-f .v{font-size:14px;font-weight:600;min-height:21px}
.fx-f .v.empty{color:var(--muted);font-weight:500}
.fx-f .v.miss{color:var(--accent)}

/* ---------- field extraction ---------- */
{
  const p = $('#fx-p'), list = $('#fx-list'), count = $('#fx-count');
  const fields = [['client','Client','Northwind Labs'],['deliv','Deliverables','Marketing site, pricing page'],['platform','Platform','Webflow'],['date','Launch date','14 November'],['budget','Budget','Not stated'],['people','Contacts','Sara Okafor, Tom Lind']];
  p.innerHTML = 'Brief: <span class="fx-s" data-f="client">Northwind Labs</span> is relaunching its website ahead of a Series A announcement. We need <span class="fx-s" data-f="deliv">a new marketing site and a refreshed pricing page</span>, designed and built in <span class="fx-s" data-f="platform">Webflow</span>. The <span class="fx-s" data-f="date">launch date is 14 November</span>, with design sign-off two weeks earlier. <span class="fx-s" data-f="budget">Budget has not been confirmed yet.</span> Main contacts are <span class="fx-s" data-f="people">Sara Okafor (Head of Marketing) and Tom Lind (CTO)</span>.';
  list.innerHTML = fields.map(f => `<div class="fx-f" data-f="${f[0]}"><span class="l">${f[1]}</span><span class="v empty">Waiting</span></div>`).join('');
  const span = k => $(`.fx-s[data-f="${k}"]`, p);
  $$('.fx-f', list).forEach(r => { r.addEventListener('mouseenter', () => span(r.dataset.f).classList.add('hov')); r.addEventListener('mouseleave', () => span(r.dataset.f).classList.remove('hov')); });
  let ts = [];
  function run(){
    ts.forEach(clearTimeout); ts = [];
    $$('.fx-s', p).forEach(s => s.classList.remove('hit'));
    $$('.fx-f .v', list).forEach(v => { v.className = 'v empty'; v.textContent = 'Waiting'; });
    count.textContent = '0 of ' + fields.length;
    fields.forEach((f, i) => ts.push(setTimeout(() => {
      span(f[0]).classList.add('hit');
      const v = $(`.fx-f[data-f="${f[0]}"] .v`, list); v.className = 'v' + (f[0] === 'budget' ? ' miss' : ''); v.innerHTML = wordsHTML(f[2]); revealWords(v, 40);
      swapText(count, (i + 1) + ' of ' + fields.length); ambient('c36', f[0] === 'budget' ? 'pop' : 'tick');
    }, 400 + i * 650)));
    ts.push(setTimeout(() => ambient('c36', 'done'), 400 + fields.length * 650));
  }
  $('#fx-replay').addEventListener('click', () => { Sound.play('tab'); run(); });
  whenSeen($('#c36'), run);
}
